"""Regenerate attributed numeric data from the pinned libdither checkout.
Usage: python3 scripts/import-ditherista.py /path/to/ditherista/libdither
No native code or application assets are copied.
"""
import json, re, sys, subprocess
from pathlib import Path
root=Path(sys.argv[1]); src=root/'src/libdither'; dest=Path('src/engine/ditherista')
sha=subprocess.check_output(['git','-C',str(root),'rev-parse','HEAD'],text=True).strip()
assert sha=='7bf49c5324b8b8d5ce321d549f89fb6c75a9d859', 'Use the reviewed libdither revision.'
header=f'// Adapted numeric data: libdither {sha}, Robert Kist.\n// See public/licenses/libdither.txt and public/licenses/libdither-additional.txt.\n// Generated by scripts/import-ditherista.py; TypeScript adaptation is modified.\n'
def arrays(file):
    text=re.sub(r'/\*.*?\*/|//[^\n]*','',(src/file).read_text(),flags=re.S)
    return {name:[int(v,16) if v.lower().startswith('0x') else float(v) if '.' in v else int(v) for v in re.findall(r'0[xX][0-9a-fA-F]+|-?\d+(?:\.\d+)?',body)] for name,body in re.findall(r'const\s+(?:int|long|double|unsigned char)\s+(\w+)\s*\[[^;=]*\]\s*=\s*\{(.*?)\};',text,re.S)}
ordered_arrays=arrays('dither_ordered_data.h'); ordered={}; meta=[]
skip={'bayer2x2_matrix','bayer4x4_matrix','bayer8x8_matrix','bayer16x16_matrix','ulichney_matrix'}
for name,w,h,div,array in re.findall(r'get_(\w+)\(void\).*?OrderedDitherMatrix_new\((\d+), (\d+), ([\d.]+), (\w+)\)',(src/'dither_ordered.c').read_text()):
    if array in skip: continue
    id='matrix-'+name.removesuffix('_matrix').replace('_','-')
    label=name.removesuffix('_matrix').replace('_',' ').replace('bayer clustered dot','Clustered dot').replace('bayer3x3','Bayer 3 × 3').replace('bayer32x32','Bayer 32 × 32').title().replace('Bayer','Bayer')
    values=ordered_arrays[array];assert len(values)==int(w)*int(h)
    ordered[id]={'width':int(w),'height':int(h),'divisor':float(div),'values':values}
    meta.append([id,label,'Ordered',f'{w} × {h} threshold matrix, adapted from libdither.'])
blue=ordered_arrays['blue_noise_raw'];assert len(blue)==128*128
ordered['blue-noise']={'width':128,'height':128,'divisor':256,'values':blue}
meta.append(['blue-noise','Blue noise','Ordered','A 128 × 128 blue-noise threshold texture by Christoph Peters (CC0), via libdither.'])
dot_arrays=arrays('dither_dotdiff_data.h'); dots={}
for name,w,h,array in re.findall(r'get_(\w+)\(void\).*?DotClassMatrix_new\((\d+), (\d+), (\w+)\)',(src/'dither_dotdiff.c').read_text()):
    id='dot-'+name.removesuffix('_class_matrix').replace('_','-');w=int(w)
    vals=dot_arrays[array]; assert sorted(vals)==list(range(w*w))
    weights=dot_arrays['guoliu8_diffusion_matrix' if name.startswith('guoliu_8') else 'guoliu16_diffusion_matrix' if name.startswith('guoliu_16') else 'default_diffusion_matrix']
    dots[id]={'size':w,'values':vals,'weights':weights}
    meta.append([id,name.removesuffix('_class_matrix').replace('_',' ').title(),'Dot diffusion','Class-ordered dot diffusion, adapted for color palettes and transparent boundaries.'])
tiles_arrays=arrays('dither_pattern_data.h'); tiles={}
for name,w,h,n,array in re.findall(r'get_(\w+)\(void\).*?TilePattern_new\((\d+), (\d+), (\d+), (\w+)\)',(src/'dither_pattern.c').read_text()):
    id='tile-'+name.removesuffix('_pattern').replace('_','-');vals=tiles_arrays[array];assert len(vals)==int(w)*int(h)*int(n)
    tiles[id]={'width':int(w),'height':int(h),'count':int(n),'values':vals}
    meta.append([id,name.removesuffix('_pattern').replace('_',' ').title()+' tiles','Tiles','Block-matched binary texture. Uses the darkest and lightest palette colors.'])
err_arrays=arrays('dither_errordiff_data.h');kernels={}
for name,w,h,div,array in re.findall(r'get_(\w+)\(void\).*?ErrorDiffusionMatrix_new\((\d+), (\d+), (\d+), (\w+)\)',(src/'dither_errordiff.c').read_text()):
    if name not in ['xot_matrix','diagonal_matrix','shiaufan2_matrix','diffusion_1d_matrix','diffusion_2d_matrix','steve_pigeon_matrix','robert_kist_matrix']:continue
    id='diff-'+name.removesuffix('_matrix').replace('_','-');vals=err_arrays[array];w=int(w);origin=vals.index(-1);ox=origin%w;oy=origin//w
    kernels[id]=[[i%w-ox,i//w-oy,v/int(div)] for i,v in enumerate(vals) if v>0]
    meta.append([id,name.removesuffix('_matrix').replace('_',' ').title(),'Diffusion','Additional diffusion kernel from libdither. Supports serpentine scanning and seeded jitter.'])
variable=arrays('dither_varerrdiff_data.h')
for name in ['ostromoukhov','zhou-fang']:
    meta.append([name,name.title().replace('Zhou-Fang','Zhou–Fang'),'Variable diffusion','Intensity-dependent diffusion coefficients. Color adaptation with reproducible noise.'])
for name,label in [('riemersma','Riemersma · Hilbert'),('riemersma-original','Riemersma original · Hilbert')]:
    meta.append([name,label,'Curve diffusion','Error history follows a space-filling Hilbert curve. Avoids row-direction artifacts.'])
for size in [2,4]:
    meta.append([f'variable-{size}',f'Variable {size} × {size}','Ordered','Adjust the threshold spacing with Matrix step.'])
# Kacker–Allebach arrays are nested; extract their complete numeric initializer.
text=(src/'dither_kallebach_data.h').read_text();body=text[text.index('=')+1:text.index(';')];allebach=[int(v) for v in re.findall(r'\b\d+\b',body)];assert len(allebach)==4096
meta.append(['kacker-allebach','Kacker–Allebach','Ordered','Alternating 32 × 32 screens reduce repeating seams. Seed selects the arrangement.'])
# Remaining method data: nested class matrices and exact L-system rules.
lippens=arrays('dither_dotlippens_data.h')
assert len(lippens['dotlippens_class_matrix'])==128*128
for i in range(1,4): assert len(lippens[f'dotlippens{i}_coe'])==25
curve_text=(src/'dither_riemersma_data.h').read_text(); curves={}
for name,base,add,exp,center,label in [
 ('hilbert_mod',2,0,1,'x','Modified Hilbert'),('peano',3,0,0,'none','Peano'),
 ('fass0',4,0,0,'none','FASS 0'),('fass1',3,0,0,'none','FASS 1'),('fass2',4,0,0,'none','FASS 2'),
 ('gosper',5,-1,0,'none','Gosper'),('fass_spiral',3,0,0,'xy','FASS spiral')]:
    axiom=re.search(rf'{name}_axiom = "([^"]*)"',curve_text)[1]
    keys=re.findall(r"'([^']*)'",re.search(rf'{name}_keys\[\] = \{{(.*?)\}};',curve_text,re.S)[1])
    rules=re.findall(r'"([^"]*)"',re.search(rf'{name}_rules\[\]\s*=\s*\{{(.*?)\}};',curve_text,re.S)[1])
    orient=[int(v) for v in re.findall(r'-?\d+',re.search(rf'{name}_orientation\[2\] = \{{(.*?)\}};',curve_text,re.S)[1])]
    curves[name]={'axiom':axiom,'rules':dict(zip(keys,rules)),'base':base,'add':add,'exp':exp,'center':center,'orientation':orient}
    for original in [False,True]:
        meta.append(['curve-'+name.replace('_','-')+('-original' if original else ''), 'Riemersma · '+label+(' · original' if original else ''),'Curve diffusion','Exact upstream L-system with streamed, pruned traversal and bounded work.'])
for i in range(7):meta.append([f'dbs-{i}',f'DBS · formula {i+1}','Optimization','Gaussian direct binary search with toggle/swap optimization. Two-ink output; bounded passes, work and resolution.'])
for name,label in [('1','Lippens–Philips 1'),('2','Lippens–Philips 2'),('3','Lippens–Philips 3'),('guoliu','Lippens · Guo–Liu'),('mese','Lippens · Mese'),('knuth','Lippens · Knuth')]:
    meta.append(['lippens-'+name,label,'Lippens–Philips','Class-bucket dot diffusion with a 5 × 5 coefficient kernel. Bounded processing.'])
for name,label in [('random','Grid · random draws'),('balanced','Grid · balanced placement')]:
    meta.append(['grid-'+name,label,'Grid','Seeded cell-based two-ink dithering. Adjustable cell width, height and minimum ink.'])
meta.append(['auto-threshold','Automatic threshold','Other','Adapts the threshold to the source tone range and mean, following libdither. Two-ink output.'])
def write(name,obj):return f'export const {name} = '+json.dumps(obj,separators=(',',':'))+';\n'
(dest/'data.ts').write_text(header+'''export interface Matrix { width:number; height:number; divisor:number; values:number[] }
export interface DotMatrix { size:number; values:number[]; weights:number[] }
export interface TileSet { width:number; height:number; count:number; values:number[] }
'''+write('orderedMatrices: Record<string,Matrix>',ordered)+write('dotMatrices: Record<string,DotMatrix>',dots)+write('tileSets: Record<string,TileSet>',tiles)+write('extraKernels: Record<string, readonly (readonly [number,number,number])[]>',kernels)+write('variableData',variable)+write('allebachMatrices',allebach)+write('lippensData', {k:v for k,v in lippens.items() if k.startswith('dotlippens')})+write('curveDefinitions: Record<string, {axiom:string;rules:Record<string,string>;base:number;add:number;exp:number;center:string;orientation:number[]}>',curves))
(dest/'catalog.ts').write_text(header+'export const additionalAlgorithms = '+json.dumps(meta,indent=2)+' as const;\n')
print(f'Imported {len(meta)} styles from {sha}')
